                (org.omg.uml.UmlPackage) ((RefObject) element)
                    .refOutermostPackage();

            LOG.log(Level.FINE, "Removing extent {0}", extent);

            modelImpl.deleteExtent(extent);
        } catch (InvalidObjectException e) {
            throw new InvalidElementException(e);
