//                } else {
//                    UMLUtil.getOwnedAttributes((Type) type1).add(property2);
//                }
                //
                ((Type) type1).getNearestPackage().getPackagedElements().add(
                        association);
                getParams().add(association);
            }
        };
        ChangeCommand cmd = new ChangeCommand(
